function render() {
  var visible = getVisibleTodos();
  var activeCount = todos.filter(function (t) { return !t.completed; }).length;
  var completedCount = todos.filter(function (t) { return t.completed; }).length;
  var totalCount = todos.length;

  // Render todo list - update existing elements in place to preserve DOM identity
  var existingLis = Array.from(dom.todoList.querySelectorAll('li'));
  var existingById = {};
  existingLis.forEach(function (li) {
    existingById[li.dataset.id] = li;
  });

  var seenIds = {};
  visible.forEach(function (todo) {
    seenIds[todo.id] = true;
    var li = existingById[todo.id];
    if (li) {
      // Update existing element
      if (todo.completed) {
        li.classList.add('completed');
      } else {
        li.classList.remove('completed');
      }
      if (editingId === todo.id) {
        li.classList.add('editing');
      } else {
        li.classList.remove('editing');
      }
      var checkbox = li.querySelector('.toggle');
      checkbox.checked = todo.completed;
      var label = li.querySelector('label');
      label.textContent = todo.title;
      var editInput = li.querySelector('.edit');
      editInput.value = todo.title;
    } else {
      // Create new element
      li = document.createElement('li');
      li.dataset.id = todo.id;
      if (todo.completed) li.classList.add('completed');
      if (editingId === todo.id) li.classList.add('editing');
      li.innerHTML =
        '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(todo.title) + '">';
      dom.todoList.appendChild(li);
    }
  });

  // Remove elements for todos no longer visible
  existingLis.forEach(function (li) {
    if (!seenIds[li.dataset.id]) {
      li.parentNode.removeChild(li);
    }
  });

